// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    address originalOwner;

    function setUp() public {
        c = new NewIntelTechMedia();
        originalOwner = address(this);
    }

    function testFuzz_property(address caller, uint256 keyIndex) public {
        vm.assume(caller != originalOwner);
        vm.assume(caller != address(0));

        uint256 beforeBalance = c.balanceOf(caller);
        uint256 beforeRemaining = c.totalRemaining();
        uint256 beforeDistributed = c.totalDistributed();
        uint256 beforeSupply = c.totalSupply();

        vm.prank(caller);
        bool ok; try c.NETM() { ok = true; } catch { ok = false; }

        if (ok) {
            uint256 afterBalance = c.balanceOf(caller);
            uint256 afterSupply = c.totalSupply();
            uint256 afterDistributed = c.totalDistributed();
            uint256 afterRemaining = c.totalRemaining();

            uint256 k = uint256(uint160(caller));
            if (keyIndex % 2 == 1) {
                k = beforeSupply;
            }

            bool supplyAccounted = afterSupply == (beforeSupply - afterBalance);
            bool undistributedAccounted = afterDistributed == (beforeDistributed - afterBalance);
            bool remainingAccounted = afterRemaining == (beforeRemaining - afterBalance);

            assertTrue(
                afterBalance == beforeBalance || (supplyAccounted && undistributedAccounted && remainingAccounted)
            );
        } else {
            assertTrue(c.balanceOf(caller) == beforeBalance);
        }
    }
}
